<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { Button, Empty, Skeleton, Tag } from 'vant'
import { httpClient } from '@/shared/http/client'
import { localTime } from '@/shared/ui/presentation'
interface Notice {kind?:string;businessNo?:string;reason?:string;id:number;caseId:string;title:string;read:boolean;createdAt:string}
interface Task {taskKey:string;caseId:string;title:string;deadline:string|null;overdue:boolean}
const router=useRouter(),notices=ref<Notice[]>([]),tasks=ref<Task[]>([]),noticeTotal=ref(0),taskTotal=ref(0),noticePage=ref(1),taskPage=ref(1),busy=ref(false),error=ref(''),message=ref('')
async function load(){busy.value=true;error.value='';try{const [inbox,todo]=await Promise.all([httpClient.get<{data:{records:Notice[];total:number}}>('/notifications',{params:{page:noticePage.value,size:20}}),httpClient.get<{data:{records:Task[];total:number}}>('/notifications/todos',{params:{page:taskPage.value,size:20}})]);notices.value=inbox.data.data.records;noticeTotal.value=inbox.data.data.total;tasks.value=todo.data.data.records;taskTotal.value=todo.data.data.total}catch(e){error.value=e instanceof Error?e.message:'通知加载失败'}finally{busy.value=false}}
async function read(id:number){try{await httpClient.post(`/notifications/${id}/read`,{});message.value='已标记为已读';await load()}catch(e){error.value=e instanceof Error?e.message:'操作失败'}}
onMounted(load)
</script>
<template><section class="notifications"><p class="notice-help">这里仅显示当前账号仍有权限访问的通知与待办。逾期只作提示，不会自动改变案件状态。</p><p v-if="message" role="status">{{ message }}</p><p v-if="error" class="inline-error" role="alert">{{ error }} <Button size="small" @click="load">重试</Button></p><Skeleton v-if="busy&&!tasks.length&&!notices.length" title :row="6"/>
  <template v-else><div class="notice-heading"><div><p class="eyebrow">TODO / 待办</p><h2>当前动作</h2></div><span>{{ taskTotal }} 项</span></div><div v-if="tasks.length"><article v-for="task in tasks" :key="task.taskKey"><button class="notice-main" @click="router.push(`/work-orders/${task.caseId}`)"><span><strong>{{ task.title }}</strong><small class="mono">{{ task.deadline?`截止 ${localTime(task.deadline)}`:'不限期' }}</small></span><Tag v-if="task.overdue" plain type="warning">已逾期</Tag></button></article></div><Empty v-else image-size="64" description="当前没有待办"/><div class="pager"><Button size="small" :disabled="busy||taskPage<=1" @click="taskPage--;load()">上一页</Button><span>{{ taskPage }} / {{ Math.max(1,Math.ceil(taskTotal/20)) }}</span><Button size="small" :disabled="busy||taskPage*20>=taskTotal" @click="taskPage++;load()">下一页</Button></div>
  <div class="notice-heading second"><div><p class="eyebrow">INBOX / 通知</p><h2>站内通知</h2></div><span>{{ noticeTotal }} 条</span></div><div v-if="notices.length"><article v-for="notice in notices" :key="notice.id"><div class="notice-main"><button class="notice-copy" @click="router.push(`/work-orders/${notice.caseId}`)"><span :class="{unread:!notice.read}"></span><span><strong>{{ notice.title }}</strong><small v-if="notice.kind==='CASE_CANCELLED'">{{ notice.businessNo }} · {{ notice.reason }}</small><small>{{ localTime(notice.createdAt) }}</small></span></button><Button size="small" plain :disabled="busy||notice.read" @click="read(notice.id)">{{ notice.read?'已读':'标记已读' }}</Button></div></article></div><Empty v-else image-size="64" description="暂无站内通知"/><div class="pager"><Button size="small" :disabled="busy||noticePage<=1" @click="noticePage--;load()">上一页</Button><span>{{ noticePage }} / {{ Math.max(1,Math.ceil(noticeTotal/20)) }}</span><Button size="small" :disabled="busy||noticePage*20>=noticeTotal" @click="noticePage++;load()">下一页</Button></div></template></section></template>
<style scoped>.notice-help{margin:0 0 20px;color:var(--color-text-secondary);font-size:13px;line-height:1.7}.notice-heading{display:flex;align-items:end;justify-content:space-between}.notice-heading h2{margin:2px 0}.notice-heading>span{color:var(--color-text-secondary);font-size:12px}.notice-heading.second{margin-top:30px}.notice-main{display:flex;width:100%;min-height:58px;align-items:center;justify-content:space-between;gap:10px;margin:0!important;padding:10px 0!important;border:0!important;background:transparent!important;text-align:left}.notice-main span,.notice-main strong,.notice-main small{display:block}.notice-main small{margin-top:4px;color:var(--color-text-secondary);font-size:12px}.notice-copy{display:flex!important;min-width:0;flex:1;align-items:center;gap:9px;margin:0!important;padding:0!important;border:0!important;background:transparent!important;text-align:left}.unread{width:7px;height:7px;flex:0 0 auto;border-radius:50%;background:var(--color-accent)}.pager{display:flex;align-items:center;justify-content:space-between;padding:14px 0;color:var(--color-text-secondary);font-size:12px}</style>
